<?php

namespace App\Modules\Assets\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Str;

/**
 * M3 — Failure Prediction (AI-driven)
 * 
 * ML-based prediction of asset failure likelihood.
 * Generated by AssetAIModule analyzing performance logs, incident history, age.
 */
class AssetFailurePrediction extends Model
{
    protected $table = 'asset_failure_predictions';

    protected $fillable = [
        'uuid',
        'asset_id',
        'prediction_date',
        'predicted_failure_date',
        'confidence_score',         // 0-100
        'failure_type',             // mechanical | electrical | software | structural | other
        'contributing_factors',     // JSON array
        'recommended_action',
        'estimated_repair_cost',
        'model_version',            // AI model version used
        'is_acknowledged',
        'acknowledged_by_user_id',
        'acknowledged_at',
    ];

    protected $casts = [
        'prediction_date'        => 'date',
        'predicted_failure_date' => 'date',
        'confidence_score'       => 'integer',
        'contributing_factors'   => 'array',
        'estimated_repair_cost'  => 'decimal:2',
        'is_acknowledged'        => 'boolean',
        'acknowledged_at'        => 'datetime',
    ];

    protected static function boot()
    {
        parent::boot();

        static::creating(function ($model) {
            if (!$model->uuid) {
                $model->uuid = (string) Str::uuid();
            }
        });
    }

    // Relationships
    public function asset(): BelongsTo
    {
        return $this->belongsTo(Assets::class, 'asset_id');
    }

    // Helpers
    public function isHighConfidence(): bool
    {
        return $this->confidence_score >= 75;
    }

    public function isImminent(): bool
    {
        return $this->predicted_failure_date <= now()->addDays(30);
    }
}
